    35→// notifyForkchoiceUpdate signals execution engine the fork choice updates. Execution engine should:
    36→// 1. Re-organizes the execution payload chain and corresponding state to make head_block_hash the head.
    37→// 2. Applies finality to the execution state: it irreversibly persists the chain of all execution payloads and corresponding state, up to and including finalized_block_hash.
    38→func (s *Service) notifyForkchoiceUpdate(ctx context.Context, arg *fcuConfig) (*enginev1.PayloadIDBytes, error) {
    39→	ctx, span := trace.StartSpan(ctx, "blockChain.notifyForkchoiceUpdate")
    40→	defer span.End()
    41→
    42→	if arg.headBlock == nil || arg.headBlock.IsNil() {
    43→		log.Error("Head block is nil")
    44→		return nil, nil
    45→	}
    46→	headBlk := arg.headBlock.Block()
    47→	if headBlk == nil || headBlk.IsNil() || headBlk.Body().IsNil() {
    48→		log.Error("Head block is nil")
    49→		return nil, nil
    50→	}
    51→	// Must not call fork choice updated until the transition conditions are met on the Pow network.
    52→	isExecutionBlk, err := blocks.IsExecutionBlock(headBlk.Body())
    53→	if err != nil {
    54→		log.WithError(err).Error("Could not determine if head block is execution block")
    55→		return nil, nil
    56→	}
    57→	if !isExecutionBlk {
    58→		return nil, nil
    59→	}
    60→	headPayload, err := headBlk.Body().Execution()
    61→	if err != nil {
    62→		log.WithError(err).Error("Could not get execution payload for head block")
    63→		return nil, nil
    64→	}
    65→	finalizedHash := s.cfg.ForkChoiceStore.FinalizedPayloadBlockHash()
    66→	justifiedHash := s.cfg.ForkChoiceStore.UnrealizedJustifiedPayloadBlockHash()
    67→	fcs := &enginev1.ForkchoiceState{
    68→		HeadBlockHash:      headPayload.BlockHash(),
    69→		SafeBlockHash:      justifiedHash[:],
    70→		FinalizedBlockHash: finalizedHash[:],
    71→	}
    72→	if len(fcs.HeadBlockHash) != 32 || [32]byte(fcs.HeadBlockHash) == [32]byte{} {
    73→		// check if we are sending FCU at genesis
    74→		hash, err := s.hashForGenesisBlock(ctx, arg.headRoot)
    75→		if errors.Is(err, errNotGenesisRoot) {
    76→			log.Error("Sending nil head block hash to execution engine")
    77→			return nil, nil
    78→		}
    79→		if err != nil {
    80→			return nil, errors.Wrap(err, "could not get head block hash")
    81→		}
    82→		fcs.HeadBlockHash = hash
    83→	}
    84→	if arg.attributes == nil {
    85→		arg.attributes = payloadattribute.EmptyWithVersion(headBlk.Version())
    86→	}
    87→	payloadID, lastValidHash, err := s.cfg.ExecutionEngineCaller.ForkchoiceUpdated(ctx, fcs, arg.attributes)
    88→	if err != nil {
    89→		switch {
    90→		case errors.Is(err, execution.ErrAcceptedSyncingPayloadStatus):
    91→			forkchoiceUpdatedOptimisticNodeCount.Inc()
    92→			log.WithFields(logrus.Fields{
    93→				"headSlot":                  headBlk.Slot(),
    94→				"headPayloadBlockHash":      fmt.Sprintf("%#x", bytesutil.Trunc(headPayload.BlockHash())),
    95→				"finalizedPayloadBlockHash": fmt.Sprintf("%#x", bytesutil.Trunc(finalizedHash[:])),
    96→			}).Info("Called fork choice updated with optimistic block")
    97→			return payloadID, nil
    98→		case errors.Is(err, execution.ErrInvalidPayloadStatus):
    99→			forkchoiceUpdatedInvalidNodeCount.Inc()
   100→			headRoot := arg.headRoot
   101→			if len(lastValidHash) == 0 {
   102→				lastValidHash = defaultLatestValidHash
   103→			}
   104→			invalidRoots, err := s.cfg.ForkChoiceStore.SetOptimisticToInvalid(ctx, headRoot, headBlk.ParentRoot(), bytesutil.ToBytes32(lastValidHash))
   105→			if err != nil {
   106→				log.WithError(err).Error("Could not set head root to invalid")
   107→				return nil, nil
   108→			}
   109→			if err := s.removeInvalidBlockAndState(ctx, invalidRoots); err != nil {
   110→				log.WithError(err).Error("Could not remove invalid block and state")
   111→				return nil, nil
   112→			}
   113→
   114→			r, err := s.cfg.ForkChoiceStore.Head(ctx)
   115→			if err != nil {
   116→				log.WithFields(logrus.Fields{
   117→					"slot":                 headBlk.Slot(),
   118→					"blockRoot":            fmt.Sprintf("%#x", bytesutil.Trunc(headRoot[:])),
   119→					"invalidChildrenCount": len(invalidRoots),
   120→				}).Warn("Pruned invalid blocks, could not update head root")
   121→				return nil, invalidBlock{error: ErrInvalidPayload, root: arg.headRoot, invalidAncestorRoots: invalidRoots}
   122→			}
   123→			b, err := s.getBlock(ctx, r)
   124→			if err != nil {
   125→				log.WithError(err).Error("Could not get head block")
   126→				return nil, nil
   127→			}
   128→			st, err := s.cfg.StateGen.StateByRoot(ctx, r)
   129→			if err != nil {
   130→				log.WithError(err).Error("Could not get head state")
   131→				return nil, nil
   132→			}
   133→			pid, err := s.notifyForkchoiceUpdate(ctx, &fcuConfig{
   134→				headState:  st,
   135→				headRoot:   r,
   136→				headBlock:  b,
   137→				attributes: arg.attributes,
   138→			})
   139→			if err != nil {
   140→				return nil, err // Returning err because it's recursive here.
   141→			}
   142→
   143→			if err := s.saveHead(ctx, r, b, st); err != nil {
   144→				log.WithError(err).Error("Could not save head after pruning invalid blocks")
   145→			}
   146→
   147→			log.WithFields(logrus.Fields{
   148→				"slot":                 headBlk.Slot(),
   149→				"blockRoot":            fmt.Sprintf("%#x", bytesutil.Trunc(headRoot[:])),
   150→				"invalidChildrenCount": len(invalidRoots),
   151→				"newHeadRoot":          fmt.Sprintf("%#x", bytesutil.Trunc(r[:])),
   152→			}).Warn("Pruned invalid blocks")
   153→			return pid, invalidBlock{error: ErrInvalidPayload, root: arg.headRoot, invalidAncestorRoots: invalidRoots}
   154→		default:
   155→			log.WithError(err).Error(ErrUndefinedExecutionEngineError)
   156→			return nil, nil
   157→		}
   158→	}
   159→	forkchoiceUpdatedValidNodeCount.Inc()
   160→	if err := s.cfg.ForkChoiceStore.SetOptimisticToValid(ctx, arg.headRoot); err != nil {
   161→		log.WithError(err).Error("Could not set head root to valid")
   162→		return nil, nil
   163→	}
   164→	// If the forkchoice update call has an attribute, update the payload ID cache.
   165→	hasAttr := arg.attributes != nil && !arg.attributes.IsEmpty()
   166→	nextSlot := s.CurrentSlot() + 1
   167→	if hasAttr && payloadID != nil {
   168→		var pId [8]byte
   169→		copy(pId[:], payloadID[:])
   170→		log.WithFields(logrus.Fields{
   171→			"blockRoot": fmt.Sprintf("%#x", bytesutil.Trunc(arg.headRoot[:])),
   172→			"headSlot":  headBlk.Slot(),
   173→			"nextSlot":  nextSlot,
   174→			"payloadID": fmt.Sprintf("%#x", bytesutil.Trunc(payloadID[:])),
   175→		}).Info("Forkchoice updated with payload attributes for proposal")
   176→		s.cfg.PayloadIDCache.Set(nextSlot, arg.headRoot, pId)
   177→		go s.firePayloadAttributesEvent(s.cfg.StateNotifier.StateFeed(), arg.headBlock, arg.headRoot, nextSlot)
   178→	} else if hasAttr && payloadID == nil && !features.Get().PrepareAllPayloads {
   179→		log.WithFields(logrus.Fields{
   180→			"blockHash": fmt.Sprintf("%#x", headPayload.BlockHash()),
   181→			"slot":      headBlk.Slot(),
   182→			"nextSlot":  nextSlot,
   183→		}).Error("Received nil payload ID on VALID engine response")
   184→	}
   185→	return payloadID, nil
   186→}
