   188→func (s *Service) firePayloadAttributesEvent(f event.SubscriberSender, block interfaces.ReadOnlySignedBeaconBlock, root [32]byte, nextSlot primitives.Slot) {
   189→	// If we're syncing a block in the past and init-sync is still running, we shouldn't fire this event.
   190→	if !s.cfg.SyncChecker.Synced() {
   191→		return
   192→	}
   193→	// the fcu args have differing amounts of completeness based on the code path,
   194→	// and there is work we only want to do if a client is actually listening to the events beacon api endpoint.
   195→	// temporary solution: just fire a blank event and fill in the details in the api handler.
   196→	f.Send(&feed.Event{
   197→		Type: statefeed.PayloadAttributes,
   198→		Data: payloadattribute.EventData{HeadBlock: block, HeadRoot: root, ProposalSlot: nextSlot},
   199→	})
   200→}
