   295→// reportInvalidBlock deals with the event that an invalid block was detected by the execution layer
   296→func (s *Service) pruneInvalidBlock(ctx context.Context, root, parentRoot, lvh [32]byte) error {
   297→	newPayloadInvalidNodeCount.Inc()
   298→	invalidRoots, err := s.cfg.ForkChoiceStore.SetOptimisticToInvalid(ctx, root, parentRoot, lvh)
   299→	if err != nil {
