    32→func (ebe *ExecutionBundleElectra) GetDecodedExecutionRequests(limits ExecutionRequestLimits) (*ExecutionRequests, error) {
    33→	requests := &ExecutionRequests{}
    34→	var prevTypeNum *uint8
    35→	for i := range ebe.ExecutionRequests {
    36→		requestType, requestListInSSZBytes, err := decodeExecutionRequest(ebe.ExecutionRequests[i])
    37→		if err != nil {
    38→			return nil, err
    39→		}
    40→		if prevTypeNum != nil && *prevTypeNum >= requestType {
    41→			return nil, errors.New("invalid execution request type order or duplicate requests, requests should be in sorted order and unique")
    42→		}
    43→		prevTypeNum = &requestType
    44→		switch requestType {
    45→		case DepositRequestType:
    46→			drs, err := unmarshalDeposits(requestListInSSZBytes, limits.Deposits)
    47→			if err != nil {
    48→				return nil, err
    49→			}
    50→			requests.Deposits = drs
    51→		case WithdrawalRequestType:
    52→			wrs, err := unmarshalWithdrawals(requestListInSSZBytes, limits.Withdrawals)
    53→			if err != nil {
    54→				return nil, err
    55→			}
    56→			requests.Withdrawals = wrs
    57→		case ConsolidationRequestType:
    58→			crs, err := unmarshalConsolidations(requestListInSSZBytes, limits.Consolidations)
    59→			if err != nil {
    60→				return nil, err
    61→			}
    62→			requests.Consolidations = crs
    63→		default:
    64→			return nil, errors.Errorf("unsupported request type %d", requestType)
    65→		}
    66→	}
    67→	return requests, nil
    68→}
