   110→func EncodeExecutionRequests(requests *ExecutionRequests) ([]hexutil.Bytes, error) {
   111→	if requests == nil {
   112→		return nil, errors.New("invalid execution requests")
   113→	}
   114→
   115→	requestsData := make([]hexutil.Bytes, 0)
   116→
   117→	// request types MUST be in sorted order starting from 0
   118→	if len(requests.Deposits) > 0 {
   119→		drBytes, err := marshalItems(requests.Deposits)
   120→		if err != nil {
   121→			return nil, errors.Wrap(err, "failed to marshal deposit requests")
   122→		}
   123→		requestData := []byte{DepositRequestType}
   124→		requestData = append(requestData, drBytes...)
   125→		requestsData = append(requestsData, requestData)
   126→	}
   127→	if len(requests.Withdrawals) > 0 {
   128→		wrBytes, err := marshalItems(requests.Withdrawals)
   129→		if err != nil {
   130→			return nil, errors.Wrap(err, "failed to marshal withdrawal requests")
   131→		}
   132→		requestData := []byte{WithdrawalRequestType}
   133→		requestData = append(requestData, wrBytes...)
   134→		requestsData = append(requestsData, requestData)
   135→	}
   136→	if len(requests.Consolidations) > 0 {
   137→		crBytes, err := marshalItems(requests.Consolidations)
   138→		if err != nil {
   139→			return nil, errors.Wrap(err, "failed to marshal consolidation requests")
   140→		}
   141→		requestData := []byte{ConsolidationRequestType}
   142→		requestData = append(requestData, crBytes...)
   143→		requestsData = append(requestsData, requestData)
   144→	}
   145→
   146→	return requestsData, nil
   147→}
